"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83236"],{32041(e){e.exports=JSON.parse('{"id":"FIN-886","slug":"discount-for-lack-of-control","term":"Discount for Lack of Control","also_known_as":[],"difficulty":"Intermediate","definition":"A discount for lack of control is a reduction applied to the value of a minority ownership stake because the holder cannot direct or influence the company\'s major decisions.","explanation":["Owning a controlling stake gives the power to choose management, set strategy, decide on dividends, sell assets or sell the whole company. A minority shareholder has none of these powers, which makes their shares less valuable per share than those of a controlling owner.","The discount for lack of control is the inverse of a control premium. For example, if a control premium of 30% applies, then a minority stake would be valued at roughly 23% less than its share of the controlling value, because 1 divided by 1.3 is about 0.77.","The size of the discount depends on the circumstances. It is larger when the controlling shareholder can act against minority interests, for example by paying high salaries to themselves instead of dividends, and smaller when minority shareholders are protected by strong legal rights or shareholder agreements.","This discount is commonly used when valuing minority stakes in private companies, such as for tax, estate planning or disputes between shareholders. It is often applied together with a discount for lack of marketability, since minority stakes in private companies typically lack both control and an easy way to sell."],"note":"","total":1500,"prev":{"slug":"discount-factor","term":"Discount Factor"},"next":{"slug":"discount-for-lack-of-marketability","term":"Discount for Lack of Marketability"}}')}}]);